'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { UsersIcon } from '@/registry/ndeko/lib/icons';

import { MEMBERS, SECTION } from './data';
import { MemberCard } from './member-card';
import { OpeningCard } from './opening-card';

/** From two columns on, this card sits in the last row, so opening its bio moves no other card. */
const SHOWN_ID = 'mei';

const RESTING_OPEN = [SHOWN_ID];

const NONE_OPEN: string[] = [];

/** `null` until someone opens a bio: closed while the demonstration plays, one open under reduced motion. */
type OpenIds = string[] | null;

function openIdsOf(state: OpenIds, shouldReduceMotion: boolean) {
  if (state !== null) {
    return state;
  }
  if (shouldReduceMotion) {
    return RESTING_OPEN;
  }
  return NONE_OPEN;
}

function withToggled(ids: readonly string[], id: string, isOpen: boolean) {
  const others = ids.filter((candidate) => candidate !== id);
  if (isOpen) {
    return [...others, id];
  }
  return others;
}

export default function TeamSections01() {
  const [state, setState] = useState<OpenIds>(null);
  const { pressed, press } = usePress<string>();
  const shouldReduceMotion = usePrefersReducedMotion();
  const openIds = openIdsOf(state, shouldReduceMotion);

  function setOpen(id: string, isOpen: boolean) {
    const next = withToggled(openIds, id, isOpen);
    setState(next);
  }

  function toggle(id: string) {
    const isOpen = openIds.includes(id);
    setOpen(id, !isOpen);
  }

  const steps = [
    { after: 2600, run: () => press(SHOWN_ID) },
    { after: PRESS_LEAD_MS, run: () => setOpen(SHOWN_ID, true) },
    { after: 4200, run: () => press(SHOWN_ID) },
    { after: PRESS_LEAD_MS, run: () => setOpen(SHOWN_ID, false) },
  ];
  const { ref } = useAutoplay<HTMLElement>(steps, {
    loopAfter: 2400,
    onReset: () => setState(null),
  });
  useKeptHeight(ref);

  return (
    <section ref={ref} className='@container min-h-[61rem]'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex max-w-2xl flex-col gap-3'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <UsersIcon className='size-4' />
            {SECTION.label}
          </p>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.lead}
          </p>
        </header>
        <ul className='grid items-start gap-3 @xl:grid-cols-2 @4xl:grid-cols-3 @6xl:grid-cols-4'>
          {MEMBERS.map((member) => (
            <li key={member.id}>
              <MemberCard
                member={member}
                isOpen={openIds.includes(member.id)}
                isPressed={pressed === member.id}
                onToggle={toggle}
              />
            </li>
          ))}
          <li>
            <OpeningCard />
          </li>
        </ul>
      </div>
    </section>
  );
}

import {
  GithubIcon,
  LinkedinBrandIcon,
  MapPinIcon,
  TwitterXIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';

import type { Member, SocialKind } from './data';
import { MemberBio } from './member-bio';

const SOCIAL_ICONS: Record<SocialKind, Icon> = {
  linkedin: LinkedinBrandIcon,
  x: TwitterXIcon,
  github: GithubIcon,
};

const SOCIAL_NAMES: Record<SocialKind, string> = {
  linkedin: 'LinkedIn',
  x: 'X',
  github: 'GitHub',
};

type MemberCardProps = {
  member: Member;
  isOpen: boolean;
  isPressed: boolean;
  onToggle: (memberId: string) => void;
};

export function MemberCard({
  member,
  isOpen,
  isPressed,
  onToggle,
}: MemberCardProps) {
  return (
    <article className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex h-full flex-col gap-4 rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <header className='flex items-start gap-3'>
        <Avatar seed={member.name} className='size-12' />
        <div className='flex min-w-0 flex-col gap-0.5'>
          <h3 className='truncate text-sm font-medium'>{member.name}</h3>
          <p className='text-muted-foreground truncate text-[13px]'>
            {member.role}
          </p>
          <p className='text-muted-foreground flex min-w-0 items-center gap-1 text-xs'>
            <MapPinIcon className='size-3.5 shrink-0' />
            <span className='truncate'>{member.location}</span>
          </p>
        </div>
      </header>
      <MemberBio
        name={member.name}
        bio={member.bio}
        isOpen={isOpen}
        isPressed={isPressed}
        onToggle={() => onToggle(member.id)}
      />
      <ul className='-mx-1.5 mt-auto flex items-center gap-0.5'>
        {member.socials.map((social) => {
          const Glyph = SOCIAL_ICONS[social.kind];
          const label = `${member.name} on ${SOCIAL_NAMES[social.kind]}`;

          return (
            <li key={social.kind}>
              <Button
                variant='ghost'
                size='icon-sm'
                nativeButton={false}
                aria-label={label}
                render={<a href={social.href} />}
                className='text-muted-foreground'
              >
                <Glyph />
              </Button>
            </li>
          );
        })}
      </ul>
    </article>
  );
}

'use client';

import {
  useEffect,
  useEffectEvent,
  useId,
  useRef,
  useState,
  type RefObject,
} from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

const TOGGLE_LABELS = ['Read more', 'Show less'];

function toggleLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Show less';
  }
  return 'Read more';
}

function clampOf(isOpen: boolean) {
  if (isOpen) {
    return 'line-clamp-none';
  }
  return 'line-clamp-3';
}

/**
 * Read more shows only when the clamp hides something, measured again at every width. While the
 * bio is open there is nothing to measure, so the last answer stands.
 */
function useCanExpand(
  textRef: RefObject<HTMLParagraphElement | null>,
  isOpen: boolean
) {
  const [canExpand, setCanExpand] = useState(true);

  const measure = useEffectEvent(() => {
    const text = textRef.current;
    if (!text || isOpen) {
      return;
    }
    const isCut = text.scrollHeight > text.clientHeight;
    setCanExpand(isCut);
  });

  useEffect(() => {
    const text = textRef.current;
    if (!text) {
      return;
    }
    const observer = new ResizeObserver(() => measure());
    observer.observe(text);
    return () => observer.disconnect();
  }, [textRef]);

  return canExpand;
}

type MemberBioProps = {
  name: string;
  bio: string;
  isOpen: boolean;
  isPressed: boolean;
  onToggle: () => void;
};

export function MemberBio({
  name,
  bio,
  isOpen,
  isPressed,
  onToggle,
}: MemberBioProps) {
  const bioId = useId();
  const textRef = useRef<HTMLParagraphElement>(null);
  const canExpand = useCanExpand(textRef, isOpen);
  const showsToggle = canExpand || isOpen;

  return (
    <div className='flex flex-col items-start gap-1'>
      <AnimatedSize className='w-full'>
        <p
          ref={textRef}
          id={bioId}
          className={cn(
            'text-muted-foreground text-[13px] leading-5 text-pretty',
            clampOf(isOpen)
          )}
        >
          {bio}
        </p>
      </AnimatedSize>
      {showsToggle && (
        <Button
          type='button'
          variant='link'
          size='sm'
          aria-expanded={isOpen}
          aria-controls={bioId}
          onClick={onToggle}
          className={cn(
            '-mx-1 h-6 px-1 text-[13px]',
            pressedQuietOf(isPressed)
          )}
        >
          <WordRoll text={toggleLabelOf(isOpen)} labels={TOGGLE_LABELS} />
          <span className='sr-only'> about {name}</span>
        </Button>
      )}
    </div>
  );
}

import { ArrowRightIcon, UserRoundPlusIcon } from '@/registry/ndeko/lib/icons';
